PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS project(id TEXT PRIMARY KEY,title TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources(version INTEGER PRIMARY KEY,text TEXT NOT NULL,sha256 TEXT NOT NULL,data TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS foundations(version INTEGER PRIMARY KEY,source_version INTEGER NOT NULL REFERENCES sources(version),data TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assets(id TEXT PRIMARY KEY,variant_id TEXT NOT NULL,version INTEGER NOT NULL,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS asset_versions(asset_id TEXT NOT NULL REFERENCES assets(id),version INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(asset_id,version));
CREATE TABLE IF NOT EXISTS media(id TEXT PRIMARY KEY,kind TEXT NOT NULL,relative_path TEXT NOT NULL,sha256 TEXT NOT NULL,size INTEGER NOT NULL,data TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS media_hash_idx ON media(sha256);
CREATE TABLE IF NOT EXISTS media_assets(media_id TEXT NOT NULL REFERENCES media(id),asset_id TEXT NOT NULL REFERENCES assets(id),variant_id TEXT NOT NULL,PRIMARY KEY(media_id,asset_id,variant_id));
CREATE TABLE IF NOT EXISTS adoptions(asset_id TEXT NOT NULL REFERENCES assets(id),variant_id TEXT NOT NULL,media_id TEXT NOT NULL REFERENCES media(id),created_at TEXT NOT NULL,PRIMARY KEY(asset_id,variant_id));
CREATE TABLE IF NOT EXISTS units(id TEXT PRIMARY KEY,episode_id TEXT NOT NULL,version INTEGER NOT NULL,data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS unit_episode_idx ON units(episode_id);
CREATE TABLE IF NOT EXISTS unit_versions(unit_id TEXT NOT NULL REFERENCES units(id),version INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(unit_id,version));
CREATE TABLE IF NOT EXISTS unit_refs(unit_id TEXT NOT NULL REFERENCES units(id),asset_id TEXT NOT NULL,variant_id TEXT NOT NULL,position INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(unit_id,position));
CREATE INDEX IF NOT EXISTS unit_refs_asset_idx ON unit_refs(asset_id,variant_id);
CREATE TABLE IF NOT EXISTS video_adoptions(unit_id TEXT PRIMARY KEY REFERENCES units(id),media_id TEXT NOT NULL REFERENCES media(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,kind TEXT NOT NULL,entity_id TEXT NOT NULL,provider TEXT NOT NULL,state TEXT NOT NULL,task_id TEXT,account_id TEXT NOT NULL,snapshot TEXT NOT NULL,prepared TEXT,receipt TEXT,result TEXT,error TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,next_attempt_at INTEGER NOT NULL DEFAULT 0,query_attempts INTEGER NOT NULL DEFAULT 0,download_attempts INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS job_resume_idx ON jobs(state,provider);
CREATE INDEX IF NOT EXISTS job_entity_idx ON jobs(entity_id,created_at);
CREATE UNIQUE INDEX IF NOT EXISTS job_active_entity_idx ON jobs(kind,entity_id) WHERE state IN ('queued','preparing','ready','submitting','submitted','processing','downloading','auth_required');
CREATE UNIQUE INDEX IF NOT EXISTS job_active_entity_v2_idx ON jobs(kind,entity_id) WHERE state IN ('queued','preparing','ready','waiting_dependency','submitting','submission_unknown','submitted','processing','succeeded','downloading','auth_required','query_failed','download_failed');
CREATE TABLE IF NOT EXISTS uploads(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs(id),receipt TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS job_media(job_id TEXT NOT NULL REFERENCES jobs(id),media_id TEXT NOT NULL REFERENCES media(id),PRIMARY KEY(job_id,media_id));
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS catalogs(provider TEXT PRIMARY KEY,data TEXT NOT NULL,fetched_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT,job_id TEXT,type TEXT NOT NULL,data TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT OR IGNORE INTO metadata VALUES('schema_version','1');
